"use client";

import { useRef } from "react";
import { motion, useInView } from "framer-motion";
import { type ReactNode } from "react";

interface FadeInProps {
  children: ReactNode;
  className?: string;
  delay?: number;
  direction?: "up" | "down" | "left" | "right";
}

export default function FadeIn({
  children,
  className = "",
  delay = 0,
  direction = "up",
}: FadeInProps) {
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: "-50px" });

  const directionOffset = {
    up: { y: 20 },
    down: { y: -20 },
    left: { x: 20 },
    right: { x: -20 },
  };

  return (
    <motion.div
      ref={ref}
      initial={{ opacity: 0, ...directionOffset[direction] }}
      animate={isInView ? { opacity: 1, x: 0, y: 0 } : {}}
      transition={{ duration: 0.5, delay, ease: "easeOut" }}
      className={className}
    >
      {children}
    </motion.div>
  );
}

import Link from "next/link";
import { ArrowRight, Beaker, Code, Database, Wrench } from "lucide-react";
import { skillCategories } from "@/data/skills";
import SectionHeading from "@/components/ui/SectionHeading";
import Badge from "@/components/ui/Badge";
import FadeIn from "@/components/animations/FadeIn";

const iconMap: Record<string, React.ElementType> = {
  beaker: Beaker,
  code: Code,
  database: Database,
  wrench: Wrench,
};

export default function SkillsPreview() {
  return (
    <section className="py-20 border-t border-border">
      <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
        <FadeIn>
          <SectionHeading
            title="Skills"
            subtitle="Core competencies across testing, automation, and quality engineering."
          />
        </FadeIn>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          {skillCategories.map((category, i) => {
            const Icon = iconMap[category.icon] || Beaker;
            return (
              <FadeIn key={category.title} delay={i * 0.1}>
                <div className="p-6 rounded-xl border border-border bg-card h-full">
                  <div className="flex items-center gap-3 mb-4">
                    <div className="p-2 rounded-lg bg-accent/10">
                      <Icon className="w-5 h-5 text-accent" />
                    </div>
                    <h3 className="text-sm font-semibold text-foreground">
                      {category.title}
                    </h3>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    {category.skills.slice(0, 6).map((skill) => (
                      <Badge key={skill.name} variant="muted">
                        {skill.name}
                      </Badge>
                    ))}
                    {category.skills.length > 6 && (
                      <Badge variant="accent">+{category.skills.length - 6}</Badge>
                    )}
                  </div>
                </div>
              </FadeIn>
            );
          })}
        </div>
        <FadeIn delay={0.4}>
          <div className="mt-8 text-center">
            <Link
              href="/skills"
              className="inline-flex items-center gap-2 text-sm font-medium text-accent hover:text-accent-hover transition-colors"
            >
              View all skills
              <ArrowRight className="w-4 h-4" />
            </Link>
          </div>
        </FadeIn>
      </div>
    </section>
  );
}

import Link from "next/link";
