          {projects.slice(0, 2).map((project, i) => (
            <FadeIn key={project.slug} delay={i * 0.1}>
              <Link
                href={`/projects/${project.slug}`}
                className="block p-6 rounded-xl border border-border bg-card hover:bg-card-hover transition-colors group"
