"use client";

import { useState } from "react";
import { AlertCircle, CheckCircle, Loader2 } from "lucide-react";
import SectionHeading from "@/components/ui/SectionHeading";
import FadeIn from "@/components/animations/FadeIn";

interface FormState {
  email: string;
  password: string;
}

interface FormErrors {
  email?: string;
  password?: string;
}

interface FormStatus {
  type: "idle" | "loading" | "success" | "error";
  message?: string;
}

function validateEmail(email: string): string | undefined {
  if (!email) return "Email is required";
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return "Please enter a valid email address";
  return undefined;
}

function validatePassword(password: string): string | undefined {
  if (!password) return "Password is required";
  if (password.length < 8) return "Password must be at least 8 characters";
  if (!/[A-Z]/.test(password)) return "Password must contain at least one uppercase letter";
  if (!/[0-9]/.test(password)) return "Password must contain at least one number";
  return undefined;
}

export default function QAGround() {
  const [form, setForm] = useState<FormState>({ email: "", password: "" });
  const [errors, setErrors] = useState<FormErrors>({});
  const [status, setStatus] = useState<FormStatus>({ type: "idle" });

  const handleChange = (field: keyof FormState, value: string) => {
    setForm((prev) => ({ ...prev, [field]: value }));
    if (errors[field]) {
      setErrors((prev) => ({ ...prev, [field]: undefined }));
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const emailError = validateEmail(form.email);
    const passwordError = validatePassword(form.password);

    if (emailError || passwordError) {
      setErrors({ email: emailError, password: passwordError });
      setStatus({ type: "error", message: "Please fix the validation errors above." });
      return;
    }

    setStatus({ type: "loading" });

    // Simulate async validation
    setTimeout(() => {
      if (form.email === "test@example.com" && form.password === "Password1") {
        setStatus({ type: "success", message: "Login successful! Redirecting..." });
      } else {
        setStatus({
          type: "error",
          message: "Invalid credentials. Try test@example.com / Password1",
        });
      }
    }, 1500);
  };

  const handleReset = () => {
    setForm({ email: "", password: "" });
    setErrors({});
    setStatus({ type: "idle" });
  };

  return (
    <section className="py-20 border-t border-border">
      <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8">
        <FadeIn>
          <SectionHeading
            title="QA Playground"
            subtitle="Interactive example demonstrating form validation — a core QA testing scenario."
            align="center"
          />
        </FadeIn>
        <FadeIn delay={0.1}>
          <div className="max-w-md mx-auto p-6 rounded-xl border border-border bg-card">
            <h3 className="text-lg font-semibold text-foreground mb-1">Login Form</h3>
            <p className="text-sm text-muted mb-6">
              Test the validation rules. This demonstrates what a QA engineer would verify.
            </p>

            <form onSubmit={handleSubmit} noValidate>
              <div className="space-y-4">
                {/* Email field */}
                <div>
                  <label
                    htmlFor="qa-email"
                    className="block text-sm font-medium text-foreground mb-1.5"
                  >
                    Email
                  </label>
                  <input
                    id="qa-email"
                    type="email"
                    value={form.email}
                    onChange={(e) => handleChange("email", e.target.value)}
                    className={`w-full px-3 py-2 rounded-lg bg-white/5 border text-foreground text-sm placeholder:text-muted focus:outline-none focus:ring-2 focus:ring-accent ${
                      errors.email ? "border-red-500" : "border-border"
                    }`}
                    placeholder="test@example.com"
                    aria-describedby={errors.email ? "email-error" : undefined}
                    aria-invalid={!!errors.email}
                  />
                  {errors.email && (
                    <p id="email-error" className="mt-1 text-xs text-red-400 flex items-center gap-1">
                      <AlertCircle className="w-3 h-3" />
                      {errors.email}
                    </p>
                  )}
                </div>

                {/* Password field */}
                <div>
                  <label
                    htmlFor="qa-password"
                    className="block text-sm font-medium text-foreground mb-1.5"
                  >
                    Password
                  </label>
                  <input
                    id="qa-password"
                    type="password"
                    value={form.password}
                    onChange={(e) => handleChange("password", e.target.value)}
                    className={`w-full px-3 py-2 rounded-lg bg-white/5 border text-foreground text-sm placeholder:text-muted focus:outline-none focus:ring-2 focus:ring-accent ${
                      errors.password ? "border-red-500" : "border-border"
                    }`}
                    placeholder="Min 8 chars, 1 uppercase, 1 number"
                    aria-describedby={errors.password ? "password-error" : undefined}
                    aria-invalid={!!errors.password}
                  />
                  {errors.password && (
                    <p id="password-error" className="mt-1 text-xs text-red-400 flex items-center gap-1">
                      <AlertCircle className="w-3 h-3" />
                      {errors.password}
                    </p>
                  )}
                </div>
              </div>

              {/* Status message */}
              {status.type !== "idle" && status.message && (
                <div
                  className={`mt-4 p-3 rounded-lg text-sm flex items-center gap-2 ${
                    status.type === "success"
                      ? "bg-green-500/10 text-green-400 border border-green-500/20"
                      : status.type === "error"
                        ? "bg-red-500/10 text-red-400 border border-red-500/20"
                        : "bg-accent/10 text-accent border border-accent/20"
                  }`}
                  role="alert"
                >
                  {status.type === "success" && <CheckCircle className="w-4 h-4 flex-shrink-0" />}
                  {status.type === "error" && <AlertCircle className="w-4 h-4 flex-shrink-0" />}
                  {status.type === "loading" && (
                    <Loader2 className="w-4 h-4 flex-shrink-0 animate-spin" />
                  )}
                  {status.message}
                </div>
              )}

              <div className="mt-6 flex gap-3">
                <button
                  type="submit"
                  disabled={status.type === "loading"}
                  className="flex-1 px-4 py-2.5 text-sm font-medium rounded-lg bg-accent text-white hover:bg-accent-hover transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {status.type === "loading" ? "Logging in..." : "Login"}
                </button>
                <button
                  type="button"
                  onClick={handleReset}
                  className="px-4 py-2.5 text-sm font-medium rounded-lg border border-border text-foreground hover:bg-white/5 transition-colors"
                >
                  Reset
                </button>
              </div>
            </form>

            <div className="mt-6 pt-4 border-t border-border">
              <p className="text-xs text-muted">
                <strong>QA Test Scenarios:</strong> Required field validation &middot; Email format
                &middot; Password complexity &middot; Loading state &middot; Success/error
                states &middot; Form reset &middot; Keyboard accessibility
              </p>
            </div>
          </div>
        </FadeIn>
      </div>
    </section>
  );
}

